const CACHE='probe-v1.8.0-rc.1';const FILES=['./','./index.html','./style.css','./app.js','./core.js','./components.js','./advisories.js','./advisory-ui.js','./serial.js','./network.js','./ip.js','./scan-ui.js','./companion-client.js','./companion-ui.js','./qualification.js','./investigation.js','./investigation-ui.js','./qualification-ui.js','./debug-ui.js','./firmware.js','./firmware-compare.js','./firmware-compare-ui.js','./firmware-ui.js','./firmware-worker.js','./sample.js','./icon.svg','./manifest.webmanifest'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('probe-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(new URL(event.request.url).pathname.startsWith('/api/'))return;if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected&&FILES.some(f=>new URL(f,self.registration.scope).href===event.request.url)){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
